def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    chars = list(alphabet)
    k = len(chars)
    cidx = {c: i for i, c in enumerate(chars)}

    # Build trie
    children = [dict()]
    bad = [False]
    for s in banned:
        u = 0
        for ch in s:
            c = cidx[ch]
            if c not in children[u]:
                children[u][c] = len(children)
                children.append(dict())
                bad.append(False)
            u = children[u][c]
        bad[u] = True

    m = len(children)
    fail = [0] * m
    delta = [[0] * k for _ in range(m)]
    order = [0]
    head = 0
    while head < len(order):
        u = order[head]
        head += 1
        for c in range(k):
            if c in children[u]:
                v = children[u][c]
                if u == 0:
                    fail[v] = 0
                else:
                    fail[v] = delta[fail[u]][c]
                bad[v] = bad[v] or bad[fail[v]]
                delta[u][c] = v
                order.append(v)
            else:
                delta[u][c] = 0 if u == 0 else delta[fail[u]][c]

    if bad[0]:
        return 1 if n == 0 else 0

    good = [u for u in range(m) if not bad[u]]
    idx = {u: i for i, u in enumerate(good)}
    g = len(good)
    M = [[0] * g for _ in range(g)]
    for u in good:
        i = idx[u]
        for c in range(k):
            v = delta[u][c]
            if not bad[v]:
                M[i][idx[v]] += 1

    def mat_mul(A, B):
        size = len(A)
        R = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ri = R[i]
            for t in range(size):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(size):
                        if Bt[j]:
                            Ri[j] += a * Bt[j]
            for j in range(size):
                Ri[j] %= MOD
        return R

    def vec_mul(v, A):
        size = len(v)
        r = [0] * size
        for t in range(size):
            a = v[t]
            if a:
                At = A[t]
                for j in range(size):
                    if At[j]:
                        r[j] += a * At[j]
        return [x % MOD for x in r]

    vec = [0] * g
    vec[idx[0]] = 1
    e = n
    while e:
        if e & 1:
            vec = vec_mul(vec, M)
        e >>= 1
        if e:
            M = mat_mul(M, M)

    return sum(vec) % MOD
